namespace bettercpp{class LunaAnalyzer{private:std::string i;void log(std::string t,std::string n){std::cout<<"[LUNA-NET]["<<t<<"] "<<n<<std::endl;}public:LunaAnalyzer(std::string iface){i=iface;}void run(){std::cout<<"=== LUNA: Network Analyzer ==="<<std::endl;log("INIT","Binding socket to: "+i);std::this_thread::sleep_for(std::chrono::milliseconds(500));log("LISTEN","Sniffing packets...");std::this_thread::sleep_for(std::chrono::milliseconds(300));std::vector<std::string> p={"TCP -> 192.168.1.45:443 [HTTPS]","UDP -> 192.168.1.12:53 [DNS]","ICMP -> 192.168.1.1 [Ping]"};for(const auto& x:p){log("CAPTURE",x);std::this_thread::sleep_for(std::chrono::milliseconds(250));}std::cout<<"------------------------------"<<std::endl;log("YIELD","Analysis completed.");}};}int main(int c,char* v[]){std::string i=(c>1)?v[1]:"eth0";bettercpp::LunaAnalyzer a(i);a.run();return 0;}
